package com.troday.api.service;
import com.fasterxml.jackson.databind.JsonNode; import com.troday.api.dto.ApiResponseDto; import com.troday.api.entity.*; import com.troday.api.repository.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.transaction.Transactional; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.math.BigDecimal; import java.time.*; import java.util.*;
@Service public class ContractService {
 private final AccountService accounts; private final ContractRepository contracts; private final ContractRevisionRepository revisions; private final RoomTenantRepository members; private final RoomRepository rooms; private final RentalHouseRepository houses; private final ViewingRepository viewings;
 public ContractService(AccountService a,ContractRepository c,ContractRevisionRepository r,RoomTenantRepository m,RoomRepository rooms,RentalHouseRepository h,ViewingRepository v){accounts=a;contracts=c;revisions=r;members=m;this.rooms=rooms;houses=h;viewings=v;}
 public ApiResponseDto<?> list(HttpServletRequest r){Long me=accounts.authenticatedUserId(r);return ok("GET",contracts.findAll().stream().filter(c->c.getLandlordId()!=null&&c.getLandlordId().equals(me)||c.getViewingTenantId()!=null&&c.getViewingTenantId().equals(me)).map(this::contractData).toList());}
 public ApiResponseDto<?> detail(HttpServletRequest r,Long id){return ok("GET",contractData(access(r,id)));}
 @Transactional public ApiResponseDto<?> create(HttpServletRequest r,JsonNode b){Long owner=accounts.authenticatedUserId(r);Long viewingId=requiredLong(b,"viewingId");Viewing v=viewings.findById(viewingId).orElseThrow(()->notFound("Không tìm thấy lịch xem"));if(!owner.equals(v.getCreatedById()))throw forbidden("Không sở hữu lịch xem");if(!"COMPLETED".equals(v.getStatus())||!"AGREED".equals(v.getRentalDecision()))throw conflict("Lịch xem chưa đủ điều kiện lập hợp đồng");if(contracts.findAll().stream().anyMatch(c->Objects.equals(c.getRoomId(),v.getRoomId())&&!Set.of("CANCELLED","TERMINATED","EXPIRED").contains(c.getStatus())))throw conflict("Phòng đã có hợp đồng đang mở");Contract c=new Contract();c.setContractNumber(text(b,"contractNumber"));c.setRoomId(v.getRoomId());c.setHouseId(v.getHouseId());c.setLandlordId(owner);c.setViewingId(viewingId);c.setViewingTenantId(v.getTenantId());c.setSource("NEW_RENTAL");c.setStatus("DRAFT");c.setStartDate(date(b,"startDate"));c.setEndDate(date(b,"endDate"));c.setRentAmount(decimal(b,"rentAmount",BigDecimal.ZERO));c.setDepositAmount(decimal(b,"depositAmount",BigDecimal.ZERO));if(c.getContractNumber().isBlank()||text(b,"content").isBlank())throw bad("contractNumber và content là bắt buộc");c=contracts.save(c);RoomTenant m=new RoomTenant();m.setContractId(c.getId());m.setRoomId(c.getRoomId());m.setTenantId(v.getTenantId());m.setFullName("Tenant "+v.getTenantId());m.setStatus("PLANNED");m.setIntakeSource("INITIAL_CONTRACT");m.setPlannedMoveInDate(c.getStartDate());m=members.save(m);ContractRevision rev=newRevision(c,b,m.getId(),1);rev.setStatus("PENDING_CONFIRMATION");rev.setLandlordConfirmedById(owner);rev.setLandlordConfirmedAt(LocalDateTime.now());rev.setSentAt(LocalDateTime.now());rev=revisions.save(rev);c.setRepresentativeRoomTenantId(m.getId());c.setInitialRepresentativeRoomTenantId(m.getId());c.setCurrentRevisionId(rev.getId());c.setStatus("PENDING_CONFIRMATION");return ok("POST",contractData(contracts.save(c)));}
 public ApiResponseDto<?> contractImpact(HttpServletRequest r,Long viewingId){Long me=accounts.authenticatedUserId(r);Viewing v=viewings.findById(viewingId).orElseThrow(()->notFound("Không tìm thấy lịch xem"));if(!v.getCreatedById().equals(me))throw forbidden("Không có quyền");return ok("GET",Map.of("futureViewingsCount",viewings.findByRoomIdAndStatus(v.getRoomId(),"SCHEDULED").size(),"pendingProposalsCount",0,"expiredProposalsCount",0,"asOf",LocalDateTime.now()));}
 public ApiResponseDto<?> revisionList(HttpServletRequest r,Long id){access(r,id);return ok("GET",revisions.findByContractIdOrderByRevisionNumberDesc(id).stream().map(this::revisionData).toList());}
 @Transactional public ApiResponseDto<?> revisionRequest(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);Contract c=access(r,id);if(!c.getViewingTenantId().equals(me))throw forbidden("Chỉ đại diện người thuê được yêu cầu sửa");if(!Set.of("PENDING_CONFIRMATION","CONFIRMED").contains(c.getStatus()))throw conflict("Hợp đồng không ở trạng thái cho phép sửa");ContractRevision old=currentRevision(c);ContractRevision n=new ContractRevision();copyRevision(old,n);n.setRevisionNumber(old.getRevisionNumber()+1);n.setStatus("DRAFT");n.setCreatedById(me);n.setTenantFeedback(text(b,"reason"));return ok("POST",revisionData(revisions.save(n)));}
 @Transactional public ApiResponseDto<?> patchRevision(HttpServletRequest r,Long cid,Long rid,JsonNode b){Long owner=accounts.authenticatedUserId(r);Contract c=access(r,cid);if(!c.getLandlordId().equals(owner))throw forbidden("Chỉ chủ trọ được sửa bản nháp");ContractRevision n=revisions.findById(rid).filter(x->x.getContractId().equals(cid)).orElseThrow(()->notFound("Không tìm thấy revision"));if(!"DRAFT".equals(n.getStatus()))throw conflict("Revision không còn là bản nháp");if(b.hasNonNull("startDate"))n.setStartDate(date(b,"startDate"));if(b.hasNonNull("endDate"))n.setEndDate(date(b,"endDate"));if(b.hasNonNull("rentAmount"))n.setRentAmount(decimal(b,"rentAmount",BigDecimal.ZERO));if(b.hasNonNull("depositAmount"))n.setDepositAmount(decimal(b,"depositAmount",BigDecimal.ZERO));if(b.hasNonNull("content"))n.setContent(text(b,"content"));return ok("PATCH",revisionData(revisions.save(n)));}
 @Transactional public ApiResponseDto<?> submitRevision(HttpServletRequest r,Long cid,Long rid){Long owner=accounts.authenticatedUserId(r);Contract c=access(r,cid);if(!c.getLandlordId().equals(owner))throw forbidden("Chỉ chủ trọ được gửi revision");ContractRevision n=revisions.findById(rid).filter(x->x.getContractId().equals(cid)).orElseThrow(()->notFound("Không tìm thấy revision"));if(!"DRAFT".equals(n.getStatus()))throw conflict("Revision không còn là bản nháp");n.setStatus("PENDING_CONFIRMATION");n.setLandlordConfirmedById(owner);n.setLandlordConfirmedAt(LocalDateTime.now());n.setSentAt(LocalDateTime.now());c.setCurrentRevisionId(n.getId());c.setStatus("PENDING_CONFIRMATION");revisions.save(n);contracts.save(c);return ok("POST",revisionData(n));}
 @Transactional public ApiResponseDto<?> confirm(HttpServletRequest r,Long id,JsonNode b){Long tenant=accounts.authenticatedUserId(r);Contract c=access(r,id);if(!tenant.equals(c.getViewingTenantId()))throw forbidden("Chỉ người thuê được xác nhận");ContractRevision n=currentRevision(c);if(!"PENDING_CONFIRMATION".equals(n.getStatus()))throw conflict("Revision không chờ xác nhận");n.setTenantConfirmedById(tenant);n.setTenantConfirmedAt(LocalDateTime.now());n.setStatus("CONFIRMED");c.setStatus("CONFIRMED");n.setAppliedAt(LocalDateTime.now());revisions.save(n);return ok("POST",contractData(contracts.save(c)));}
 @Transactional public ApiResponseDto<?> moveIn(HttpServletRequest r,Long id,JsonNode b){Long owner=accounts.authenticatedUserId(r);Contract c=access(r,id);if(!c.getLandlordId().equals(owner))throw forbidden("Chỉ chủ trọ được xác nhận vào ở");if(!"CONFIRMED".equals(c.getStatus()))throw conflict("Hợp đồng chưa được xác nhận");LocalDate d=b!=null&&b.hasNonNull("moveInDate")?date(b,"moveInDate"):c.getStartDate();for(RoomTenant m:members.findAll())if(c.getId().equals(m.getContractId())&&"PLANNED".equals(m.getStatus())){m.setStatus("ACTIVE");m.setMoveInDate(d);m.setMoveInConfirmedById(owner);m.setMoveInConfirmedAt(LocalDateTime.now());members.save(m);}c.setStatus("ACTIVE");return ok("POST",contractData(contracts.save(c)));}
 @Transactional public ApiResponseDto<?> cancel(HttpServletRequest r,Long id,JsonNode b){Long owner=accounts.authenticatedUserId(r);Contract c=access(r,id);if(!c.getLandlordId().equals(owner))throw forbidden("Chỉ chủ trọ được hủy");if("ACTIVE".equals(c.getStatus()))throw conflict("Hợp đồng đã active");if(!Set.of("DRAFT","PENDING_CONFIRMATION","CONFIRMED").contains(c.getStatus()))throw conflict("Hợp đồng không thể hủy");c.setStatus("CANCELLED");for(RoomTenant m:members.findAll())if(c.getId().equals(m.getContractId())&&"PLANNED".equals(m.getStatus())){m.setStatus("CANCELLED");m.setCancellationReason(text(b,"reason"));members.save(m);}return ok("POST",contractData(contracts.save(c)));}
 @Transactional public ApiResponseDto<?> cancelMember(HttpServletRequest r,Long cid,Long mid,JsonNode b){Long owner=accounts.authenticatedUserId(r);Contract c=access(r,cid);if(!c.getLandlordId().equals(owner))throw forbidden("Chỉ chủ trọ được hủy thành viên");RoomTenant m=members.findById(mid).filter(x->x.getContractId().equals(cid)).orElseThrow(()->notFound("Không tìm thấy thành viên"));if(!"PLANNED".equals(m.getStatus()))throw conflict("Chỉ hủy được thành viên chưa vào ở");if(Objects.equals(c.getRepresentativeRoomTenantId(),mid))throw conflict("Không thể hủy đại diện");m.setStatus("CANCELLED");m.setCancellationReason(text(b,"reason"));return ok("POST",memberData(members.save(m)));}
 @Transactional public ApiResponseDto<?> importPaper(HttpServletRequest r,JsonNode b){Long owner=accounts.authenticatedUserId(r);Long room=requiredLong(b,"roomId");RentalHouse h=houses.findById(rooms.findById(room).orElseThrow(()->notFound("Không tìm thấy phòng")).getHouseId()).orElseThrow(()->notFound("Không tìm thấy nhà"));if(!h.getLandlordId().equals(owner))throw forbidden("Không sở hữu nhà");Contract c=new Contract();c.setContractNumber(text(b,"contractNumber"));c.setRoomId(room);c.setHouseId(h.getId());c.setLandlordId(owner);c.setSource("PAPER_IMPORT");c.setPaperDocumentFileId(requiredLong(b,"paperDocumentFileId"));c.setStartDate(date(b,"startDate"));c.setEndDate(date(b,"endDate"));c.setRentAmount(decimal(b,"rentAmount",BigDecimal.ZERO));c.setDepositAmount(decimal(b,"depositAmount",BigDecimal.ZERO));c.setStatus("DRAFT");return ok("POST",contractData(contracts.save(c)));}
 private Contract access(HttpServletRequest r,Long id){Long me=accounts.authenticatedUserId(r);Contract c=contracts.findById(id).orElseThrow(()->notFound("Không tìm thấy hợp đồng"));if(!Objects.equals(c.getLandlordId(),me)&&!Objects.equals(c.getViewingTenantId(),me))throw forbidden("Không có quyền với hợp đồng");return c;}
 private ContractRevision currentRevision(Contract c){if(c.getCurrentRevisionId()==null)throw conflict("Hợp đồng chưa có revision");return revisions.findById(c.getCurrentRevisionId()).orElseThrow(()->notFound("Không tìm thấy revision hiện hành"));}
 private ContractRevision newRevision(Contract c,JsonNode b,Long member, int number){ContractRevision n=new ContractRevision();n.setContractId(c.getId());n.setRevisionNumber(number);n.setCreatedById(c.getLandlordId());n.setKind("INITIAL");n.setStartDate(c.getStartDate());n.setEndDate(c.getEndDate());n.setEffectiveFrom(c.getStartDate());n.setRentAmount(c.getRentAmount());n.setDepositAmount(c.getDepositAmount());n.setContent(text(b,"content"));n.setMembersSnapshot("[{\"roomTenantId\":"+member+"}]");n.setRepresentativeRoomTenantId(member);return n;}
 private void copyRevision(ContractRevision o,ContractRevision n){n.setContractId(o.getContractId());n.setCreatedById(o.getCreatedById());n.setKind(o.getKind());n.setStartDate(o.getStartDate());n.setEndDate(o.getEndDate());n.setEffectiveFrom(o.getEffectiveFrom());n.setRentAmount(o.getRentAmount());n.setDepositAmount(o.getDepositAmount());n.setContent(o.getContent());n.setMembersSnapshot(o.getMembersSnapshot());n.setRepresentativeRoomTenantId(o.getRepresentativeRoomTenantId());}
 private Map<String,Object> contractData(Contract c){Map<String,Object> m=new LinkedHashMap<>();m.put("id",c.getId());m.put("contractNumber",c.getContractNumber());m.put("roomId",c.getRoomId());m.put("houseId",c.getHouseId());m.put("landlordId",c.getLandlordId());m.put("viewingId",c.getViewingId());m.put("viewingTenantId",c.getViewingTenantId());m.put("status",c.getStatus());m.put("source",c.getSource());m.put("startDate",c.getStartDate());m.put("endDate",c.getEndDate());m.put("rentAmount",c.getRentAmount());m.put("depositAmount",c.getDepositAmount());m.put("currentRevisionId",c.getCurrentRevisionId());m.put("members",members.findAll().stream().filter(x->c.getId().equals(x.getContractId())).map(this::memberData).toList());return m;}
 private Map<String,Object> revisionData(ContractRevision n){Map<String,Object> m=new LinkedHashMap<>();m.put("id",n.getId());m.put("contractId",n.getContractId());m.put("revisionNumber",n.getRevisionNumber());m.put("kind",n.getKind());m.put("status",n.getStatus());m.put("startDate",n.getStartDate());m.put("endDate",n.getEndDate());m.put("rentAmount",n.getRentAmount());m.put("depositAmount",n.getDepositAmount());m.put("content",n.getContent());m.put("tenantConfirmedAt",n.getTenantConfirmedAt());return m;}
 private Map<String,Object> memberData(RoomTenant m){Map<String,Object> x=new LinkedHashMap<>();x.put("id",m.getId());x.put("contractId",m.getContractId());x.put("roomId",m.getRoomId());x.put("tenantId",m.getTenantId());x.put("fullName",m.getFullName());x.put("status",m.getStatus());x.put("plannedMoveInDate",m.getPlannedMoveInDate());x.put("moveInDate",m.getMoveInDate());return x;}
 private LocalDate date(JsonNode b,String k){try{return LocalDate.parse(text(b,k));}catch(Exception e){throw bad(k+" không hợp lệ");}}private BigDecimal decimal(JsonNode b,String k,BigDecimal d){if(!b.hasNonNull(k))return d;try{return new BigDecimal(b.get(k).asText());}catch(Exception e){throw bad(k+" không hợp lệ");}}private Long requiredLong(JsonNode b,String k){if(b==null||!b.hasNonNull(k))throw bad(k+" là bắt buộc");return b.get(k).asLong();}private String text(JsonNode b,String k){return b!=null&&b.hasNonNull(k)?b.get(k).asText():"";}private ApiResponseDto<?> ok(String m,Object d){return ApiResponseDto.ok("/api/v1",m,d);}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);}private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
